import{_ as o,C as a,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"POS overview","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/get-started/pos-overview.md","filePath":"master/sales/point-of-sale/get-started/pos-overview.md","lastUpdated":1793074831000}'),l={name:"master/sales/point-of-sale/get-started/pos-overview.md"};function g(d,e,h,p,u,m){const r=a("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="pos-overview" tabindex="-1">POS overview <a class="header-anchor" href="#pos-overview" aria-label="Permalink to &quot;POS overview&quot;">​</a></h1><p>Point of Sale has an admin side for managers and a terminal side for cashiers. This page is a map of both. You learn what each menu does, how retail and restaurant registers differ, and which numbers POS creates for sessions, orders and receipts.</p><blockquote><p><strong>In simple words:</strong> Managers set things up in the admin app. Cashiers sell on the terminal. Both read the same data.</p></blockquote><h2 id="the-admin-app" tabindex="-1">The admin app <a class="header-anchor" href="#the-admin-app" aria-label="Permalink to &quot;The admin app&quot;">​</a></h2><p>Open the <strong>Point of Sale</strong> app. The top menu has six entries.</p>',5)),s(r,{src:"/images1/pos/pos_admin_menu.png",alt:"Point of Sale admin top menu: Dashboard, Orders, Products, Reporting, Configurations and Settings"}),e[1]||(e[1]=t('<h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><p>The <strong>Dashboard</strong> shows one card for each register. A card tells you the register name, its type (restaurant or retail) and whether a session is open. Click <strong>Continue Selling</strong> to go back to an open session. Click <strong>Open Register</strong> to start a new one.</p><p>A second screen shows filters (<strong>Terminals</strong>, <strong>Date Range</strong>, <strong>Products</strong>, <strong>POS Categories</strong>, <strong>Salespersons</strong>, <strong>Customers</strong>), the figures <strong>Open Sessions</strong>, <strong>Orders</strong>, <strong>Revenue</strong> and <strong>Failed Operations</strong>, and a <strong>Top Products</strong> chart. See <a href="./../reporting/dashboard.html">Dashboard</a>.</p><h3 id="orders" tabindex="-1">Orders <a class="header-anchor" href="#orders" aria-label="Permalink to &quot;Orders&quot;">​</a></h3><p>The <strong>Orders</strong> menu groups five pages:</p><ul><li><strong><em>Orders:</em></strong> Every POS order, with tabs <strong>Default</strong>, <strong>Settled</strong>, <strong>Ongoing</strong> and <strong>Refunds</strong>. See <a href="./../orders-payments/orders.html">Orders</a>.</li><li><strong><em>Sessions:</em></strong> Every shift, with tabs <strong>Default</strong>, <strong>Open</strong>, <strong>Closing Control</strong> and <strong>Closed</strong>. You can run <strong>Cash In/Out</strong> and <strong>Close Session</strong> here. See <a href="./../sessions/">Sessions</a>.</li><li><strong><em>Payments:</em></strong> Every payment taken at the till. See <a href="./../orders-payments/payments.html">Payments</a>.</li><li><strong><em>Preparation Printers:</em></strong> Printers that send kitchen or bar tickets. See <a href="./../payments-setup/preparation-printers.html">Preparation printers</a>.</li><li><strong><em>Customers:</em></strong> The people who bought at your registers. See <a href="./../orders-payments/customers.html">Customers</a>.</li></ul><h3 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h3><p>The <strong>Products</strong> page lists items you can sell at the till. Tabs include <strong>Goods</strong>, <strong>Services</strong>, <strong>Favorites</strong>, <strong>Archived</strong>, <strong>Inventory Management</strong>, <strong>Components</strong> and <strong>POS</strong>. See <a href="./../products-pricing/products.html">Products</a>.</p><h3 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h3><p><strong>Reporting</strong> holds three reports: <strong>Orders</strong>, <strong>Sales Details</strong> and <strong>Session Report</strong>. See <a href="./../reporting/">Reporting</a>.</p><h3 id="configurations" tabindex="-1">Configurations <a class="header-anchor" href="#configurations" aria-label="Permalink to &quot;Configurations&quot;">​</a></h3><p><strong>Configurations</strong> is where you build the setup:</p><ul><li><strong>Payment Methods</strong>, <strong>Coins/Bills</strong>, <strong>Point of Sale</strong> (your registers), <strong>Floors</strong>, <strong>Note Models</strong>.</li><li><strong>Taxes</strong>.</li><li><strong>Products</strong>: <strong>PoS Product Categories</strong> and <strong>Attributes</strong>.</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p><strong>Settings</strong> holds module-wide rules on three pages: <strong>Manage Accounts</strong>, <strong>Manage Products</strong> and <strong>Manage Inventory</strong>. See <a href="./pos-settings.html">POS settings</a>.</p><h2 id="the-cashier-terminal" tabindex="-1">The cashier terminal <a class="header-anchor" href="#the-cashier-terminal" aria-label="Permalink to &quot;The cashier terminal&quot;">​</a></h2><p>The terminal is a separate full-screen app with three pages in its top bar.</p><ul><li><strong><em>Registers:</em></strong> Lists your registers. Each one shows its name, short code and state. Click <strong>Resume</strong> on an open register or <strong>Open register</strong> on a closed one.</li><li><strong><em>Home:</em></strong> The start page of one register. A restaurant register shows the floor plan.</li><li><strong><em>Orders:</em></strong> All active orders of this register, with their status. You refund, invoice and reprint receipts here.</li></ul>',18)),s(r,{src:"/images1/pos/pos_terminal_registers.png",alt:"Terminal Registers page listing Spice Route Kitchen & Bar and TechNest Electronics, each with a Resume button"}),e[2]||(e[2]=t('<h2 id="retail-and-restaurant-mode" tabindex="-1">Retail and restaurant mode <a class="header-anchor" href="#retail-and-restaurant-mode" aria-label="Permalink to &quot;Retail and restaurant mode&quot;">​</a></h2><p>Each register is either retail or restaurant. You choose this with the <strong>Is a Bar/Restaurant</strong> toggle on the register form.</p><table tabindex="0"><thead><tr><th></th><th>Retail</th><th>Restaurant</th></tr></thead><tbody><tr><td>Example</td><td>TechNest Electronics</td><td>Spice Route Kitchen &amp; Bar</td></tr><tr><td>Start screen</td><td>Order screen with product grid</td><td>Floor plan with tables</td></tr><tr><td>Tables</td><td>No</td><td>Yes, grouped by floor</td></tr><tr><td>Split bill, early receipt, eat in or take out</td><td>No</td><td>Optional</td></tr><tr><td>Actions button</td><td>Cancel order</td><td>Guests, Transfer / Merge, Cancel order</td></tr></tbody></table><p>See <a href="./set-up-a-register.html">Set up a register</a> for each option.</p><h2 id="numbers-pos-creates" tabindex="-1">Numbers POS creates <a class="header-anchor" href="#numbers-pos-creates" aria-label="Permalink to &quot;Numbers POS creates&quot;">​</a></h2><p>POS numbers things for you.</p><ul><li><strong><em>Short code:</em></strong> The prefix you type on the register form, for example <strong>TNE</strong>.</li><li><strong><em>Session number:</em></strong> Short code plus <code>SESSION</code> plus five digits, such as <code>TNE/SESSION/00002</code>.</li><li><strong><em>Order number:</em></strong> Short code plus five digits, such as <code>TNE/00001</code>. A refund order shows the original number with <strong>REFUND</strong>.</li><li><strong><em>Receipt number:</em></strong> Three groups, such as <code>00004-009-0001</code>. They are the register number, the session number and the order number inside that session.</li><li><strong><em>Tracking number:</em></strong> A short number on the order. Cashiers use it to call out an order.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Search orders on the terminal by order number, receipt number or customer name.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./set-up-a-register.html">Set up a register</a></li><li><a href="./../selling/terminal-overview.html">Terminal overview</a></li><li><a href="./../">Point of Sale</a></li></ul>',10))])}const b=o(l,[["render",g]]);export{f as __pageData,b as default};
